// Pixelify's 2 and 5 read oddly — 'Studdy Digits' (public/studdy-digits.otf,
// generated by scripts/gen-digits.mjs) redraws JUST those two glyphs on
// Pixelify's exact advance and cap height, so nothing jitters or resizes.
const digitFix = new FontFace('Studdy Digits', `url(${import.meta.env.BASE_URL}studdy-digits.otf)`, {
  unicodeRange: 'U+0032, U+0035',
  weight: '100 900',
})
document.fonts.add(digitFix)
digitFix.load().catch(() => {})
